CREATE OR REPLACE FUNCTION profile.point_transaction_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.entry_type IS NULL THEN
        NEW.entry_type := CASE WHEN NEW.action = 'credit' THEN 'earned' ELSE 'spent' END;
    END IF;
    RETURN NEW;
END;
$function$;
